"use client"

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Separator } from "@/components/ui/separator"
import {
  Building2,
  Users,
  Globe,
  Mail,
  Phone,
  Calendar,
  DollarSign,
  FileText,
  Edit,
  Trash2,
} from "lucide-react"
import type { Company } from "@/lib/api"

interface CompanyDetailsModalProps {
  company: Company | null
  open: boolean
  onOpenChange: (open: boolean) => void
  onEdit: (company: Company) => void
  onDelete: (company: Company) => void
}

function formatCurrency(amount: number | null): string {
  if (amount === null) return "N/A"
  return `RWF ${amount.toLocaleString()}`
}

function formatDate(dateString: string | null): string {
  if (!dateString) return "N/A"
  return new Date(dateString).toLocaleDateString("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
  })
}

export function CompanyDetailsModal({
  company,
  open,
  onOpenChange,
  onEdit,
  onDelete,
}: CompanyDetailsModalProps) {
  if (!company) return null

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <div className="flex justify-between items-start">
            <div>
              <DialogTitle className="text-2xl">{company.name}</DialogTitle>
              <DialogDescription className="capitalize">
                {company.industry} • {company.companyType?.replace(/_/g, " ")}
              </DialogDescription>
            </div>
            <Badge
              variant="outline"
              className={
                company.isActive
                  ? "bg-chart-1/10 text-chart-1 border-chart-1/20"
                  : "bg-warning/10 text-warning border-warning/20"
              }
            >
              {company.isActive ? "Active" : "Inactive"}
            </Badge>
          </div>
        </DialogHeader>

        <div className="space-y-6">
          {/* Description */}
          {company.description && (
            <div>
              <h3 className="text-sm font-semibold mb-2 flex items-center gap-2">
                <FileText className="h-4 w-4" />
                Description
              </h3>
              <p className="text-sm text-muted-foreground">{company.description}</p>
            </div>
          )}

          <Separator />

          {/* Key Metrics */}
          <div>
            <h3 className="text-sm font-semibold mb-3">Key Metrics</h3>
            <div className="grid grid-cols-2 gap-4">
              <div className="flex items-start gap-3">
                <DollarSign className="h-5 w-5 text-muted-foreground mt-0.5" />
                <div>
                  <p className="text-sm font-medium">Annual Revenue</p>
                  <p className="text-lg font-serif font-semibold">
                    {formatCurrency(company.annualRevenue)}
                  </p>
                </div>
              </div>
              <div className="flex items-start gap-3">
                <Users className="h-5 w-5 text-muted-foreground mt-0.5" />
                <div>
                  <p className="text-sm font-medium">Employees</p>
                  <p className="text-lg font-serif font-semibold">
                    {company.employeeCount || "N/A"}
                  </p>
                </div>
              </div>
            </div>
          </div>

          <Separator />

          {/* Contact Information */}
          <div>
            <h3 className="text-sm font-semibold mb-3">Contact Information</h3>
            <div className="space-y-3">
              {company.email && (
                <div className="flex items-center gap-3">
                  <Mail className="h-4 w-4 text-muted-foreground" />
                  <a
                    href={`mailto:${company.email}`}
                    className="text-sm text-primary hover:underline"
                  >
                    {company.email}
                  </a>
                </div>
              )}
              {company.phoneNumber && (
                <div className="flex items-center gap-3">
                  <Phone className="h-4 w-4 text-muted-foreground" />
                  <a
                    href={`tel:${company.phoneNumber}`}
                    className="text-sm text-primary hover:underline"
                  >
                    {company.phoneNumber}
                  </a>
                </div>
              )}
              {company.website && (
                <div className="flex items-center gap-3">
                  <Globe className="h-4 w-4 text-muted-foreground" />
                  <a
                    href={company.website}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-sm text-primary hover:underline"
                  >
                    {company.website}
                  </a>
                </div>
              )}
            </div>
          </div>

          <Separator />

          {/* Company Details */}
          <div>
            <h3 className="text-sm font-semibold mb-3">Company Details</h3>
            <div className="grid grid-cols-2 gap-4">
              {company.ceo && (
                <div>
                  <p className="text-xs text-muted-foreground mb-1">CEO</p>
                  <p className="text-sm font-medium">{company.ceo}</p>
                </div>
              )}
              {company.establishedDate && (
                <div>
                  <p className="text-xs text-muted-foreground mb-1">Established</p>
                  <p className="text-sm font-medium">
                    {formatDate(company.establishedDate)}
                  </p>
                </div>
              )}
              {company.taxId && (
                <div>
                  <p className="text-xs text-muted-foreground mb-1">Tax ID</p>
                  <p className="text-sm font-medium font-mono">{company.taxId}</p>
                </div>
              )}
              {company.registrationNumber && (
                <div>
                  <p className="text-xs text-muted-foreground mb-1">
                    Registration Number
                  </p>
                  <p className="text-sm font-medium font-mono">
                    {company.registrationNumber}
                  </p>
                </div>
              )}
            </div>
          </div>

          {/* Notes */}
          {company.notes && (
            <>
              <Separator />
              <div>
                <h3 className="text-sm font-semibold mb-2">Notes</h3>
                <p className="text-sm text-muted-foreground">{company.notes}</p>
              </div>
            </>
          )}

          {/* Created By */}
          {company.createdBy && (
            <>
              <Separator />
              <div>
                <h3 className="text-sm font-semibold mb-2">Created By</h3>
                <div className="flex items-center gap-3">
                  <div className="h-8 w-8 rounded-full bg-primary/10 flex items-center justify-center">
                    <span className="text-xs font-semibold text-primary">
                      {company.createdBy.name?.charAt(0).toUpperCase()}
                    </span>
                  </div>
                  <div>
                    <p className="text-sm font-medium">{company.createdBy.name}</p>
                    <p className="text-xs text-muted-foreground">
                      {company.createdBy.email}
                    </p>
                  </div>
                </div>
              </div>
            </>
          )}
        </div>

        <DialogFooter className="gap-2">
          <Button
            variant="outline"
            onClick={() => onDelete(company)}
            className="text-destructive hover:text-destructive"
          >
            <Trash2 className="mr-2 h-4 w-4" />
            Delete
          </Button>
          <Button onClick={() => onEdit(company)}>
            <Edit className="mr-2 h-4 w-4" />
            Edit Company
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}